import type { Config } from '../config.js';
import { isRlnError, type RlnErrorName } from './errors.js';
import { rln, type RlnNode } from './nodes.js';
import { fromApiAmount, toApiAmount } from './units.js';

export interface ReadyResult {
  /** Mnemonic generated by /init in this call (node was fresh and none was configured). */
  generatedMnemonic?: string;
  initialized: boolean;
  unlocked: boolean;
}

// init (if fresh) + unlock (if locked). Safe to call any time: a restarted node comes back
// locked, so the seed, the e2e script and the server all call this before using a node.
export async function ensureReady(node: RlnNode, cfg: Config): Promise<ReadyResult> {
  if (!node.password) {
    throw new Error(`RLN_${node.name.toUpperCase()}_PASSWORD is not set (see .env.example)`);
  }
  const result: ReadyResult = { initialized: false, unlocked: false };

  try {
    const res = await rln(
      node,
      '/init',
      node.client.POST('/init', { body: { password: node.password, mnemonic: node.mnemonic ?? null } }),
    );
    result.initialized = true;
    if (!node.mnemonic) result.generatedMnemonic = res.mnemonic;
  } catch (e) {
    // AlreadyInitialized: fine. An already unlocked node answers /init with UnlockedNode.
    if (!isRlnError(e, 'AlreadyInitialized') && !isRlnError(e, 'UnlockedNode')) throw e;
  }

  try {
    await rln(
      node,
      '/unlock',
      node.client.POST('/unlock', {
        body: {
          password: node.password,
          indexer_url: cfg.RLN_INDEXER_URL,
          announce_addresses: [],
          announce_alias: node.name,
          ldk_chain_sync: {
            mode: 'BlockSync',
            config: {
              bitcoind_rpc_username: cfg.RLN_BITCOIND_RPC_USER,
              bitcoind_rpc_password: cfg.RLN_BITCOIND_RPC_PASSWORD,
              bitcoind_rpc_host: cfg.RLN_BITCOIND_RPC_HOST,
              bitcoind_rpc_port: cfg.RLN_BITCOIND_RPC_PORT,
            },
          },
        },
      }),
    );
    result.unlocked = true;
  } catch (e) {
    if (!isRlnError(e, 'AlreadyUnlocked')) throw e;
  }

  return result;
}

export async function nodeInfo(node: RlnNode) {
  return rln(node, '/nodeinfo', node.client.GET('/nodeinfo'));
}

export const FEE_RATE = 5; // sat/vB, regtest

export async function btcBalance(node: RlnNode) {
  return rln(node, '/btcbalance', node.client.POST('/btcbalance', { body: { skip_sync: false } }));
}

export async function newAddress(node: RlnNode): Promise<string> {
  return (await rln(node, '/address', node.client.POST('/address'))).address;
}

// Create UTXOs that RGB allocations can be bound to. Returns false when the node already
// has enough free ones (AllocationsAlreadyAvailable).
export async function createUtxos(node: RlnNode, num: number): Promise<boolean> {
  try {
    await rln(
      node,
      '/createutxos',
      node.client.POST('/createutxos', {
        body: { up_to: true, num, size: null, fee_rate: FEE_RATE, skip_sync: false },
      }),
    );
    return true;
  } catch (e) {
    if (isRlnError(e, 'AllocationsAlreadyAvailable')) return false;
    throw e;
  }
}

export async function colorableUtxos(node: RlnNode): Promise<number> {
  const res = await rln(
    node,
    '/listunspents',
    node.client.POST('/listunspents', { body: { settled_only: true, skip_sync: false } }),
  );
  return res.unspents.filter((u) => u.utxo.colorable).length;
}

// The node's own indexer (electrs) can lag a moment behind esplora after a block is mined:
// retry an operation while it fails with one of the given transient errors.
export async function retryOn<T>(names: RlnErrorName[], fn: () => Promise<T>, tries = 10): Promise<T> {
  for (let i = 1; ; i++) {
    try {
      return await fn();
    } catch (e) {
      if (i >= tries || !names.some((n) => isRlnError(e, n))) throw e;
      await new Promise((r) => setTimeout(r, 1000));
    }
  }
}

export interface AssetBalance {
  settled: bigint;
  future: bigint;
  spendable: bigint;
}

// A node learns about a contract only when it first receives the asset; until then
// /assetbalance answers UnknownContractId, which here means a zero balance.
export async function getAssetBalance(node: RlnNode, assetId: string): Promise<AssetBalance> {
  try {
    const b = await rln(node, '/assetbalance', node.client.POST('/assetbalance', { body: { asset_id: assetId } }));
    return { settled: fromApiAmount(b.settled), future: fromApiAmount(b.future), spendable: fromApiAmount(b.spendable) };
  } catch (e) {
    if (isRlnError(e, 'UnknownContractId')) return { settled: 0n, future: 0n, spendable: 0n };
    throw e;
  }
}

// The asset id changes on every reset, so the demo asset is looked up by ticker.
export async function findNiaByTicker(node: RlnNode, ticker: string) {
  const res = await rln(
    node,
    '/listassets',
    node.client.POST('/listassets', { body: { filter_asset_schemas: ['Nia'] } }),
  );
  return (res.nia ?? []).find((a) => a.ticker === ticker);
}

export async function issueNia(node: RlnNode, ticker: string, name: string, supply: bigint, precision: number) {
  const res = await rln(
    node,
    '/issueassetnia',
    node.client.POST('/issueassetnia', { body: { amounts: [toApiAmount(supply)], ticker, name, precision } }),
  );
  return res.asset;
}
